query:
NODE VALUE incoming_sum SumAgg<INT64> = 0
TABLE incoming_results {id STRING, total INT64}

MATCH (source:player)-[edge:follow]->(target:player)
PER PATH {
  SET target.@incoming_sum += coalesce(edge.degree, 0)
}

MATCH (p:player)
PER NODE (p) {
  EXPORT p.id, p.@incoming_sum INTO incoming_results
}

FOR row IN incoming_results
RETURN row.id AS id, row.total AS total
